/** How long each look stays before the next. */
export const LOOK_MS = 30000;

export const lookCount = (key) => 1 + (LOOKS[key]?.length || 0);

/** Which look shows at `now`: from the clock, so every part of the screen (and the tab bar) changes together. */
export const lookIndex = (key, now = Date.now()) => Math.floor(now / LOOK_MS) % lookCount(key);

/** The burst when a look changes: x/y in % of the top, r in px, drift dx/dy in px, delay in s. */
export function swapSparks(theme, n = 18) {
  const rnd = seeded(31 + (theme.look || 0));
  const paint = [theme.accent, ...theme.paint];
  return Array.from({ length: n }, (_, i) => {
    const ang = rnd() * Math.PI * 2;
    const dist = 40 + rnd() * 70;
    return { x: 10 + rnd() * 80, y: 20 + rnd() * 50, r: 2 + rnd() * 3, dx: Math.round(Math.cos(ang) * dist), dy: Math.round(Math.sin(ang) * dist), fill: paint[i % paint.length], delay: +(0.35 + rnd() * 0.3).toFixed(2) };
  });
}

/** The festival's theme in look `n`, with `key` and `look` added. */
export function lookOf(key, n = 0) {
  const i = n % lookCount(key);
  return { ...themeOf(key), ...(i ? LOOKS[key][i - 1] : null), key, look: i };
}

/** The drawing area every motif is laid out in, drawn at about phone width. */
export const MOTIF_BOX = { w: 360, h: 96 };

/** Decorations that are a pattern repeat across a wide screen; the rest are one centred piece. */
export const motifRepeats = (themeKey) => ['toran', 'lights', 'splash', 'stars'].includes(themeOf(themeKey).motif);

/** Same numbers every render (no flicker, web and app alike). */
function seeded(seed) {
  let s = seed;
  return () => { s = (s * 1103515245 + 12345) % 2147483648; return s / 2147483648; };
}

const quad = (p0, p1, p2, t) => ({
  x: (1 - t) ** 2 * p0.x + 2 * (1 - t) * t * p1.x + t * t * p2.x,
  y: (1 - t) ** 2 * p0.y + 2 * (1 - t) * t * p1.y + t * t * p2.y,
});

const star = (cx, cy, r) => {
  const i = r * 0.38;
  return `M${cx},${cy - r} L${cx + i},${cy - i} L${cx + r},${cy} L${cx + i},${cy + i} L${cx},${cy + r} L${cx - i},${cy + i} L${cx - r},${cy} L${cx - i},${cy - i} Z`;
};

/**
 * The decoration as plain shapes in MOTIF_BOX:
 *   { t: 'circle', cx, cy, r, fill, o? }   { t: 'path', d, fill?, stroke?, sw?, o? }
 * and how each moves, so the website and the app animate the same parts:
 *   anim   'sway' (swings from px,py) · 'twinkle' · 'flicker' · 'float' · 'breathe' · 'fall'
 *   g      shapes with the same g move together (a strand, a kite, the lantern)
 *   delay  seconds, so they do not all move in step
 */
export function motifShapes(themeKey) {
  const th = themeOf(themeKey);
  const [a, b, c, d, e] = th.paint;
  const { w } = MOTIF_BOX;
  const out = [];
  const rnd = seeded(7);

  if (th.motif === 'toran') {
    // A jhalar: a fine gold border, scallops hanging from it, and at each join a
    // small marigold bell on a thread that sways. Line art, not cartoon.
    out.push({ t: 'path', d: `M0,3.5 L${w},3.5`, stroke: e, sw: 1.1 });
    out.push({ t: 'path', d: `M0,7 L${w},7`, stroke: e, sw: 0.6, o: 0.7 });
    for (let x = 0; x < w; x += 24) {
      out.push({ t: 'path', d: `M${x},7 Q${x + 12},21 ${x + 24},7`, stroke: e, sw: 0.9 });
      out.push({ t: 'circle', cx: x + 12, cy: 14.2, r: 1.1, fill: e });
    }
    for (let i = 0, x = 24; x < w; i += 1, x += 24) {
      const long = i % 2 === 0;
      const y = long ? 34 : 26;
      const sway = { g: `b${i}`, anim: 'sway', px: x, py: 7, delay: (i % 5) * 0.4 };
      out.push({ t: 'path', d: `M${x},7 L${x},${y - 4}`, stroke: e, sw: 0.6, ...sway });
      out.push({ t: 'path', d: `M${x - 2.6},${y - 4.5} Q${x},${y - 7.5} ${x + 2.6},${y - 4.5}`, fill: d, ...sway });
      out.push({ t: 'circle', cx: x, cy: y, r: long ? 3.6 : 3, fill: long ? a : c, ...sway });
      out.push({ t: 'circle', cx: x - 0.9, cy: y - 0.9, r: long ? 1.1 : 0.9, fill: '#FFFFFF', o: 0.55, ...sway });
    }
  } else if (th.motif === 'lights') {
    // A marigold toran across the top: swags of flowers between nails, mango leaves hanging and swaying at each nail.
    const nails = [0, 90, 180, 270, 360];
    const flower = (x, y) => {
      out.push({ t: 'circle', cx: x, cy: y, r: 5.2, fill: '#FBBF24' });
      for (let k = 0; k < 8; k += 1) {
        const ang = (k / 8) * Math.PI * 2;
        out.push({ t: 'circle', cx: x + Math.cos(ang) * 4.2, cy: y + Math.sin(ang) * 4.2, r: 2.3, fill: '#F59E0B' });
      }
      out.push({ t: 'circle', cx: x, cy: y, r: 2, fill: '#C2410C' });
    };
    for (let n = 0; n < nails.length - 1; n += 1) {
      const p0 = { x: nails[n], y: 3 }; const p1 = { x: nails[n] + 45, y: 22 }; const p2 = { x: nails[n + 1], y: 3 };
      out.push({ t: 'path', d: `M${p0.x},${p0.y} Q${p1.x},${p1.y} ${p2.x},${p2.y}`, stroke: '#7C2D12', sw: 1, o: 0.6 });
      for (let k = 1; k < 7; k += 1) { const q = quad(p0, p1, p2, k / 7); flower(q.x, q.y); }
    }
    nails.slice(1, -1).forEach((x, i) => {
      const leaf = { anim: 'sway', g: `leaf${i}`, px: x, py: 4, delay: i * 0.5 };
      [-7, 0, 7].forEach((tip) => {
        out.push({ t: 'path', d: `M${x},4 C${x + 6 + tip / 2},9 ${x + 4 + tip},20 ${x + tip},27 C${x - 4 + tip},20 ${x - 6 + tip / 2},9 ${x},4 Z`, fill: '#2F7D4A', ...leaf });
        out.push({ t: 'path', d: `M${x},5 L${x + tip},26`, stroke: '#1F5A35', sw: 0.8, ...leaf });
      });
      flower(x, 4);
    });
  } else if (th.motif === 'splash') {
    // Holi colour: soft clouds of gulal.
    for (let k = 0; k < 26; k += 1) {
      out.push({ t: 'circle', cx: rnd() * w, cy: rnd() * 90, r: 3 + rnd() * 13, fill: th.paint[k % th.paint.length], o: 0.35 + rnd() * 0.35, anim: 'breathe', delay: (k % 6) * 0.4 });
    }
  } else if (th.motif === 'kites') {
    // Kites in the sky, each on its own string.
    [[40, 30, a], [120, 18, b], [210, 40, c], [300, 22, d], [255, 70, a]].forEach(([x, y, fill], k) => {
      const s = k === 4 ? 9 : 13;
      const fly = { g: `k${k}`, anim: 'float', px: x, py: y, delay: k * 0.6 };
      out.push({ t: 'path', d: `M${x},${y - s} L${x + s},${y} L${x},${y + s * 1.3} L${x - s},${y} Z`, fill, ...fly });
      out.push({ t: 'path', d: `M${x},${y - s} L${x},${y + s * 1.3} M${x - s},${y} L${x + s},${y}`, stroke: '#FFFFFF', sw: 0.8, o: 0.7, ...fly });
      out.push({ t: 'path', d: `M${x},${y + s * 1.3} Q${x + 18},${y + 40} ${x - 6},${y + 70}`, stroke: e, sw: 0.7, o: 0.45, ...fly });
    });
  } else if (th.motif === 'crescent') {
    // A crescent moon, stars and a hanging lantern.
    out.push({ t: 'circle', cx: 300, cy: 36, r: 22, fill: a });
    out.push({ t: 'circle', cx: 310, cy: 30, r: 20, fill: c });
    for (let k = 0; k < 14; k += 1) out.push({ t: 'path', d: star(rnd() * 260, 8 + rnd() * 70, 2 + rnd() * 3.5), fill: k % 3 ? b : a, o: 0.9, anim: 'twinkle', delay: (k % 7) * 0.3 });
    const lantern = { g: 'lantern', anim: 'sway', px: 60, py: 0, delay: 0 };
    out.push({ t: 'path', d: 'M60,0 L60,22', stroke: a, sw: 1, ...lantern });
    out.push({ t: 'path', d: 'M52,22 L68,22 L72,40 L60,50 L48,40 Z', fill: a, o: 0.95, ...lantern });
    out.push({ t: 'circle', cx: 60, cy: 36, r: 12, fill: a, o: 0.25, ...lantern });
  } else {
    // Stars and falling snow.
    for (let k = 0; k < 10; k += 1) out.push({ t: 'path', d: star(rnd() * w, 8 + rnd() * 70, 3 + rnd() * 4), fill: a, anim: 'twinkle', delay: k * 0.37 });
    for (let k = 0; k < 30; k += 1) out.push({ t: 'circle', cx: rnd() * w, cy: rnd() * 92, r: 0.8 + rnd() * 1.8, fill: b, o: 0.4 + rnd() * 0.5, anim: 'fall', delay: (k % 10) * 0.6 });
  }
  return out;
}

/**
 * Soft sunburst rays for the light themes, behind everything, in a box `w`×`h`
 * (the whole band): wedges from a point above the middle, white and faint.
 */
export function rayShapes(w = 360, h = 420) {
  const cx = w / 2; const cy = -h * 0.12; const R = h * 1.6;
  const out = [];
  for (let deg = 12; deg < 168; deg += 12) {
    const a1 = (deg * Math.PI) / 180; const a2 = ((deg + 5) * Math.PI) / 180;
    out.push({ t: 'path', d: `M${cx},${cy} L${cx + R * Math.cos(a1)},${cy + R * Math.sin(a1)} L${cx + R * Math.cos(a2)},${cy + R * Math.sin(a2)} Z`, fill: '#FFFFFF', o: 0.16 });
  }
  return out;
}

/**
 * The jhalar edge for bars (header, footer, the bottom tab bar): one 24×12
 * repeat of a fine line, a scallop and a bead, to tile along an edge.
 * `flip` hangs it upward (for a bar's top edge).
 */
export function jhalarTile(color, flip = false) {
  const g = flip ? ' transform="translate(0 12) scale(1 -1)"' : '';
  return `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="12" viewBox="0 0 24 12"><g${g} fill="none" stroke="${color}" stroke-width="1"><path d="M0,1.5 L24,1.5"/><path d="M0,1.5 Q12,13 24,1.5"/></g><circle cx="12" cy="${flip ? 4.4 : 7.6}" r="1.6" fill="${color}"/></svg>`;
}

/** The jhalar edge as one strip `width` wide (apps: drawn with SvgXml). */
export function jhalarStrip(color, width, flip = false) {
  const tile = jhalarTile(color, flip).replace(/^<svg[^>]*>|<\/svg>$/g, '');
  const n = Math.ceil(width / 24);
  const tiles = Array.from({ length: n }, (_, i) => `<g transform="translate(${i * 24} 0)">${tile}</g>`).join('');
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${n * 24}" height="12" viewBox="0 0 ${n * 24} 12">${tiles}</svg>`;
}

/** The jhalar edge as a CSS background image (websites). */
export const jhalarCss = (color, flip = false) => `url("data:image/svg+xml,${encodeURIComponent(jhalarTile(color, flip))}")`;

/**
 * The shapes in drawing order, those sharing a `g` gathered into one group
 * (moved as one): [{ key, anim, px, py, delay, shapes }].
 */
export function motifGroups(shapes) {
  const out = [];
  for (const [i, sh] of shapes.entries()) {
    const last = out[out.length - 1];
    if (sh.g && last?.key === sh.g) { last.shapes.push(sh); continue; }
    out.push({ key: sh.g || `x${i}`, anim: sh.anim || null, px: sh.px ?? sh.cx ?? 0, py: sh.py ?? sh.cy ?? 0, delay: sh.delay || 0, shapes: [sh] });
  }
  return out;
}

/** "20% off" or "₹100 off", from a live promo. */
export const offerHeadline = (p) => (p.type === 'percent' ? `${p.discountValue}% off` : `${formatPaise(p.discountValue)} off`);

/** "up to ₹150, on ₹499+", or ''. */
export function offerTerms(p) {
  const parts = [];
  if (p.type === 'percent' && p.maxDiscountPaise) parts.push(`up to ${formatPaise(p.maxDiscountPaise)}`);
  if (p.minOrderPaise) parts.push(`on ${formatPaise(p.minOrderPaise)}+`);
  return parts.join(', ');
}

// A festive tile's tag: admin's own badge, else the service's real starting price; never an invented discount.
export function tileTag(tile, service) {
  if (tile?.badge) return tile.badge;
  const from = service?.fromPaise;
  return Number.isFinite(from) && from > 0 ? `From ${formatPaise(from)}` : null;
}

// The arched top of the festive panel, in a 400×40 box; the same curve carries the marquee lights.
export const ARCH = { w: 400, h: 40 };
export const archEdge = 'M0,40 L0,24 Q0,16 10,16 L132,16 C162,16 170,2 200,2 C230,2 238,16 268,16 L390,16 Q400,16 400,24 L400,40';
export const archLights = 'M8,22 Q8,20 12,20 L132,20 C162,20 170,6 200,6 C230,6 238,20 268,20 L388,20 Q392,20 392,22';

// The festive panel's tiles: admin's picks that are live here first, then other live services with a photo and a real starting price, cheapest first.
export function festivePicks(tiles, services, photoOf, max = 5) {
  services = services || [];
  const byCode = new Map(services.map((s) => [s.code, s]));
  const picked = (tiles || []).map((t) => ({ ...t, service: byCode.get(t.serviceCode) })).filter((t) => t.service);
  const taken = new Set(picked.map((t) => t.serviceCode));
  const more = services
    .filter((s) => !taken.has(s.code) && Number.isFinite(s.fromPaise) && s.fromPaise > 0 && photoOf(s))
    .sort((a, b) => a.fromPaise - b.fromPaise)
    .map((s) => ({ serviceCode: s.code, title: s.name, service: s }));
  return [...picked, ...more].slice(0, max);
}
